// ───────── Planos: versiones y zonas señaladas con coordenadas normalizadas ─────────
export function plansTab(body, w) {
  const box = h('div', { class: 'stack' }); body.append(box); const manage = w.can?.manage;
  const draw = () => load(box, () => get(`/api/works/${w.id}/plans`), ({ items }) => {
    if (!items.length) box.append(empty('Sin planos', 'Cargue un plano en PDF o imagen para señalar zonas y relacionarlas con partidas.'));
    for (const pl of items) { const cur = pl.versions[0]; const view = h('div', {});
      const sel = h('select', { 'aria-label': 'Versión del plano', onchange: (e) => viewer(view, pl.versions.find((v) => v.id === e.target.value), w, draw) }, pl.versions.map((v) => h('option', { value: v.id }, `Versión ${v.version} · ${v.status === 'vigente' ? 'vigente' : 'sustituida'} · ${v.annotations.length} zona(s)`)));
      box.append(card(pl.name, h('div', { class: 'tools' }, h('label', { class: 'f' }, 'Versión', sel), manage ? btn('Sustituir por una nueva versión', () => uploadPlan(w, pl, draw), 'ghost') : null), h('p', { class: 'small muted' }, 'Al sustituir un plano, las zonas señaladas permanecen en la versión donde se hicieron. Las marcas indican ubicación; no se calculan medidas a partir del plano.'), view)); viewer(view, cur, w, draw); }
    if (manage) box.append(h('div', { class: 'actions' }, btn('Cargar plano', () => uploadPlan(w, null, draw), 'primary')));
  });
  draw();
}
