  return formDialog({ title: plan ? `Nueva versión de ${plan.name}` : 'Cargar plano', fields: [plan ? null : { key: 'name', label: 'Nombre del plano', required: true }, plan ? null : { key: 'discipline', label: 'Disciplina' }, { key: 'note', label: 'Nota de la versión' }], extra: () => up, submit: (v) => { if (!att) throw Object.assign(new Error('Espere a que termine la carga del archivo.'), { data: {} }); return plan ? post(`/api/plans/${plan.id}/versions`, { ...v, attachmentId: att }) : post(`/api/works/${w.id}/plans`, { ...v, attachmentId: att }); } }).then((r) => r && done());
